select count(*) as n, md5(string_agg(h, '' order by h)) as h from (select md5(concat_ws(chr(31), "path", "title", "kind", "module", "format", "artifact_url", "docs_id", "tab_name", "rev", "content", "pdf_path", "sha256")) h from public.documents where "path" in ('modules/F1-histories-of-making/specs/F1.3.md', 'modules/F1-histories-of-making/specs/F1.4.md', 'schema/README.md', 'schema/registers.md', 'schema/unit-spec-template.md')) s;